INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('jijiu', 30, '第31章', 'jijiu-30', '䜛谀争语相觝触。
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('shangshu', 16, '尚书·商书·典宝', 'shangshu-16', '亡佚。《汩作九共槀饫》《帝告厘沃》《汤征》《汝鸠汝方》《夏社疑至臣扈》《典宝》《明居》《沃丁》《咸乂》《伊陟原命》《仲丁》《河亶甲》《祖乙》《分器》《旅巢命》《归禾》《嘉禾》《成王政》《将蒲姑》《贿肃慎之命》《亳姑》——是秦始皇焚书后散掉的《书序》篇题，只有一句小序，没有正文。', '', ''),
  ('shangshu', 19, '尚书·商书·明居', 'shangshu-19', '亡佚。《汩作九共槀饫》《帝告厘沃》《汤征》《汝鸠汝方》《夏社疑至臣扈》《典宝》《明居》《沃丁》《咸乂》《伊陟原命》《仲丁》《河亶甲》《祖乙》《分器》《旅巢命》《归禾》《嘉禾》《成王政》《将蒲姑》《贿肃慎之命》《亳姑》——是秦始皇焚书后散掉的《书序》篇题，只有一句小序，没有正文。', '', ''),
